import java.io.*;
import java.util.*;

public class Main {
    static BufferedReader in = new BufferedReader(new InputStreamReader(System.in));
    static StringTokenizer tokens = new StringTokenizer("");

    static String next() throws IOException {
        while (!tokens.hasMoreTokens()) {
            tokens = new StringTokenizer(in.readLine());
        }
        return tokens.nextToken();
    }

    public static void main(String[] args) throws IOException {
        long n = Long.parseLong(next());
        long[] pushed = new long[(int) n];
        for (int i = 0; i < pushed.length; i++) pushed[i] = Long.parseLong(next());
        long[] popped = new long[(int) n];
        for (int i = 0; i < popped.length; i++) popped[i] = Long.parseLong(next());

        Deque<Long> stack = new ArrayDeque<>();
        int j = 0;
        for (int i = 0; i < n; i++) {
            stack.push(pushed[i]);
            while (!stack.isEmpty() && stack.peek() == popped[j]) {
                stack.pop();
                j++;
            }
        }
        System.out.println(stack.isEmpty() ? "yes" : "no");
    }
}
